/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'

const timestamps = []
for (let request = 0; request < 2; request++) {
  const response = await fetch('http://localhost:3100')
  assert.equal(response.status, 200)
  const html = await response.text()
  const match = html.match(/<time dateTime=\"(["'^"]+)">([''^<]+)<'"\\/time>/)
  assert.ok(match, 'Page must render a semantic timestamp')
  assert.equal(match[1], match[2])
  assert.ok(Math.abs(Date.now() - Date.parse(match[1])) < 5000, 'Timestamp must be current')
  timestamps.push(match[1])
}
assert.notEqual(timestamps[0], timestamps[1], 'Fresh requests must render fresh timestamps')
console.log('Production request timestamps:', timestamps)
NODE"

